begin;
insert into public.resources(id,kind,title,subtitle,description,org,tags,location,deadline,featured,status,tone,mark,meta,url,lessons)
select id,kind,title,subtitle,description,org,tags,location,deadline,featured,status,tone,mark,meta,url,coalesce(lessons,'[]'::jsonb)
from jsonb_to_recordset('[{"id":"11111111-1111-4111-8111-111111111101","kind":"competition","title":"青年创新挑战赛","subtitle":"让你的第一个想法，走向更大的舞台","description":"围绕校园生活与可持续发展，提出一个有价值的解决方案。个人或 2–5 人团队均可参加。提交项目说明、原型与 3 分钟展示视频。此赛事为产品示例，报名流程仅用于体验。","org":"青年创新实验室 · 示例","tags":["创新创业","跨学科","零门槛"],"location":"线上","deadline":"2026-11-15","featured":true,"status":"published","tone":"pink","mark":"✳","meta":"团队赛 · 免费参与"},{"id":"11111111-1111-4111-8111-111111111102","kind":"internship","title":"产品设计实习生","subtitle":"把好奇心，变成真实的产品体验","description":"参与用户访谈、信息架构与交互原型设计。希望你熟悉 Figma，愿意从真实问题出发。每周至少 3 天，持续 3 个月。请准备作品集。此岗位为示例内容，并非真实招聘。","org":"Arcadia Studio · 示例","tags":["产品设计","Figma","远程友好"],"location":"上海 / 远程","deadline":"2026-11-30","featured":true,"status":"published","tone":"blue","mark":"A","meta":"150–200 元 / 天 · 示例"},{"id":"11111111-1111-4111-8111-111111111103","kind":"competition","title":"校园 AI 应用黑客松","subtitle":"48 小时，让灵感跑起来","description":"使用 AI 工具解决你身边的一个小问题。开发、设计、运营同学可以跨专业组队。活动包含导师指导与作品展示。示例活动，无真实主办关系。","org":"校园创客社区 · 示例","tags":["人工智能","编程","组队"],"location":"线上","deadline":"2026-10-28","featured":true,"status":"published","tone":"yellow","mark":"AI","meta":"48 小时 · 2–4 人组队"},{"id":"11111111-1111-4111-8111-111111111104","kind":"internship","title":"内容运营实习生","subtitle":"让一个好故事，被更多人看见","description":"负责青年成长主题的选题、内容制作与社区运营。每周 3 天，提供真实项目实践。此岗位为示例内容。","org":"未明成长工作室 · 示例","tags":["内容运营","写作","新媒体"],"location":"北京","deadline":"2026-11-20","featured":false,"status":"published","tone":"green","mark":"未","meta":"120–180 元 / 天 · 示例"},{"id":"11111111-1111-4111-8111-111111111105","kind":"tool","title":"Figma","subtitle":"把脑海里的想法，画成可交互的原型","description":"多人协作的设计与原型工具。适合界面设计、团队共创和作品集制作。访问官方站点了解当前免费与教育方案。","org":"Figma","tags":["产品设计","原型","协作"],"location":"在线工具","deadline":null,"featured":true,"status":"published","tone":"purple","mark":"figma","meta":"设计与原型","url":"https://www.figma.com/"},{"id":"11111111-1111-4111-8111-111111111106","kind":"tool","title":"Notion","subtitle":"为你的知识和项目，建一个家","description":"用文档、数据库和任务视图组织课程笔记、项目计划与成长记录。访问官方站点了解当前方案。","org":"Notion","tags":["知识管理","效率","协作"],"location":"在线工具","deadline":null,"featured":true,"status":"published","tone":"neutral","mark":"N","meta":"笔记与知识管理","url":"https://www.notion.so/"},{"id":"11111111-1111-4111-8111-111111111107","kind":"tool","title":"GitHub","subtitle":"让你的代码，成为可展示的作品","description":"托管代码、跟踪问题、协作开发，并通过公开仓库展示项目过程。","org":"GitHub","tags":["编程","开源","协作"],"location":"在线工具","deadline":null,"featured":false,"status":"published","tone":"neutral","mark":"git","meta":"代码与开源协作","url":"https://github.com/"},{"id":"11111111-1111-4111-8111-111111111108","kind":"course","title":"从 0 到 1，做出第一个产品","subtitle":"一条属于产品新人的修炼路径","description":"用一个校园小问题贯穿需求、设计与验证，完成你的第一个作品集项目。课程为站内原创示例讲义。","org":"宗门学堂","tags":["产品设计","创新创业","作品集"],"location":"自学课程","deadline":null,"featured":true,"status":"published","tone":"purple","mark":"01","meta":"6 节课 · 约 1.5 小时","lessons":[{"id":"21111111-1111-4111-8111-111111111101","title":"从一个真实问题开始","minutes":15,"body":"先观察，再提出方案。记录三个你在校园生活中遇到的不便，并选出一个反复出现的问题。\n\n练习：用「谁，在什么场景下，遇到了什么困难」写出问题陈述。不要提前写解决方案。\n\n产出：一段清晰的问题描述，以及一个你可以访谈的真实用户。"},{"id":"21111111-1111-4111-8111-111111111102","title":"做一次有用的用户访谈","minutes":18,"body":"邀请三位经历过问题的同学。请他们讲述最近一次发生的具体过程，避免问「你会不会用我的产品」。\n\n练习：记录触发场景、当前解决办法和最困难的步骤。\n\n产出：三条来自具体事件的洞察。"},{"id":"21111111-1111-4111-8111-111111111103","title":"把需求整理成用户旅程","minutes":12,"body":"将用户的任务拆成开始、行动和完成三个阶段，列出每一步的问题。\n\n练习：找出一个可以明显改善的节点。\n\n产出：一张简单旅程图和一个优先解决的需求。"},{"id":"21111111-1111-4111-8111-111111111104","title":"用 Figma 做出可点击原型","minutes":20,"body":"先在纸上画出核心流程，再使用 Figma 连接页面。控制在三到五个界面。\n\n练习：确保用户可以从入口完成目标任务。\n\n产出：一个可点击的低保真原型。"},{"id":"21111111-1111-4111-8111-111111111105","title":"验证想法，接受真实反馈","minutes":15,"body":"请三位同学独立使用原型。给任务，不给操作提示。观察卡住的地方。\n\n练习：记录任务成功率和最严重的三个问题。\n\n产出：按影响排序的改进清单。"},{"id":"21111111-1111-4111-8111-111111111106","title":"将实践写成作品集","minutes":15,"body":"以问题、过程、选择和结果组织作品集。展示你做了什么，也解释为什么。\n\n练习：用一页写清你负责的部分与验证结果。\n\n产出：一篇可以分享的项目案例。"}]},{"id":"11111111-1111-4111-8111-111111111109","kind":"course","title":"AI 工具与高效学习","subtitle":"从提问，到形成自己的知识体系","description":"通过三个练习学习拆解任务、校验信息和建立个人学习记录。","org":"宗门学堂","tags":["人工智能","效率","知识管理"],"location":"自学课程","deadline":null,"featured":false,"status":"published","tone":"green","mark":"AI","meta":"3 节课 · 约 45 分钟","lessons":[{"id":"21111111-1111-4111-8111-111111111107","title":"把问题问清楚","minutes":15,"body":"说明背景、目标、约束和期望格式。\n\n练习：把「帮我学习」改成一个具体请求。\n\n产出：一条包含学习目标和可用时间的提示词。"},{"id":"21111111-1111-4111-8111-111111111108","title":"验证而不是照单全收","minutes":15,"body":"对日期、数据、法律与专业结论核对原始来源。\n\n练习：选择一段 AI 回答，标出需要核实的三处事实。\n\n产出：一份带原始链接的核查笔记。"},{"id":"21111111-1111-4111-8111-111111111109","title":"用输出巩固学习","minutes":15,"body":"将知识改写为自己的解释，并在真实任务中应用。\n\n练习：给同学讲解一个概念，用例子验证理解。\n\n产出：一篇简短学习总结。"}]},{"id":"11111111-1111-4111-8111-111111111110","kind":"project","title":"做一个校园闲置地图","subtitle":"让闲置物品，找到新的主人","description":"设计一个基于校园区域的闲置物品发现工具。项目涵盖调研、交互、前端和内容运营，适合第一次跨专业协作。建议 4 周完成可演示原型。示例项目，可申请参与体验。","org":"校园共创计划 · 示例","tags":["产品设计","编程","可持续"],"location":"远程协作","deadline":"2026-11-05","featured":true,"status":"published","tone":"green","mark":"地","meta":"4 周 · 招募 3 位伙伴"},{"id":"11111111-1111-4111-8111-111111111111","kind":"project","title":"你的第一份成长作品集","subtitle":"把做过的事，变成被看见的经历","description":"围绕一段学习或实践经历，制作一个包含目标、过程与结果的个人作品集。可独立完成，也可以邀请伙伴互相反馈。","org":"宗门共修","tags":["作品集","写作","产品设计"],"location":"独立 / 组队","deadline":null,"featured":true,"status":"published","tone":"pink","mark":"集","meta":"2 周 · 开放参与"}]'::jsonb) as x(id uuid,kind text,title text,subtitle text,description text,org text,tags text[],location text,deadline date,featured boolean,status text,tone text,mark text,meta text,url text,lessons jsonb)
on conflict(id) do nothing;
insert into public.posts(id,author,avatar,title,body,tags,type,date)
select id,author,avatar,title,body,tags,type,date
from jsonb_to_recordset('[{"id":"31111111-1111-4111-8111-111111111101","author":"林小满","avatar":"林","title":"校园 AI 黑客松，寻找一位设计伙伴","body":"我们已经有前端和算法同学，想做一个帮助新生发现校园资源的助手。希望你对用户体验感兴趣，愿意一起把想法做出来。每周可以投入 4–6 小时。","tags":["人工智能","产品设计","组队"],"type":"recruitment","date":"2026-10-09"},{"id":"31111111-1111-4111-8111-111111111102","author":"陈一","avatar":"陈","title":"第一次实习前，作品集到底该放什么？","body":"最近在整理课程项目，发现过程里的思考比最后的界面更难讲清楚。大家会怎样展示自己的取舍和验证过程？分享一个你觉得有用的结构吧。","tags":["作品集","实习"],"type":"discussion","date":"2026-10-08"},{"id":"31111111-1111-4111-8111-111111111103","author":"许知夏","avatar":"许","title":"一起做校园闲置地图，欢迎前端同学","body":"需求访谈已经做完，希望找一位 React 同学一起实现原型。四周完成一个可以放入作品集的小项目，时间可商量。","tags":["编程","可持续","组队"],"type":"recruitment","date":"2026-10-07"}]'::jsonb) as x(id uuid,author text,avatar text,title text,body text,tags text[],type text,date date)
on conflict(id) do nothing;
commit;
